{"op":"add","path":"/root","value":"page"}
{"op":"add","path":"/elements/page","value":{"type":"Stack","props":{"direction":"vertical","gap":"lg"},"children":["header","invoices"]}}
{"op":"add","path":"/elements/header","value":{"type":"ResultHeader","props":{"eyebrow":"Invoice extraction","title":"Your invoice, read","subtitle":"Totals, parties and classification pulled from the document."},"children":[]}}
{"op":"add","path":"/elements/invoices","value":{"type":"Stack","props":{"direction":"vertical","gap":"lg"},"repeat":{"statePath":"/result","key":"invoice_id"},"children":["invoice-section"]}}
{"op":"add","path":"/elements/invoice-section","value":{"type":"Section","props":{"title":{"$item":"vendor"},"lede":{"$item":"invoice_number"}},"children":["figures-grid","record-split","raw-text-fold"]}}
{"op":"add","path":"/elements/figures-grid","value":{"type":"Grid","props":{"columns":4,"gap":"sm"},"children":["fact-total","fact-net","fact-vat","fact-issued"]}}
{"op":"add","path":"/elements/fact-total","value":{"type":"Fact","props":{"label":"Total","value":{"$item":"amount_incl_tax"}},"children":[]}}
{"op":"add","path":"/elements/fact-net","value":{"type":"Fact","props":{"label":"Net","value":{"$item":"amount_excl_tax"}},"children":[]}}
{"op":"add","path":"/elements/fact-vat","value":{"type":"Fact","props":{"label":"VAT","value":{"$item":"vat_amount"}},"children":[]}}
{"op":"add","path":"/elements/fact-issued","value":{"type":"Fact","props":{"label":"Issued","value":{"$item":"issue_date"},"detail":{"$item":"time"}},"children":[]}}
{"op":"add","path":"/elements/record-split","value":{"type":"Split","props":{"ratio":"2:1","gap":"lg"},"children":["details-column","classification-rail"]}}
{"op":"add","path":"/elements/details-column","value":{"type":"Stack","props":{"direction":"vertical","gap":"none"},"children":["detail-seller","detail-seller-address","detail-siret","detail-vat-number","detail-billed-to","detail-billing-address","detail-invoice-number","detail-reference","detail-time","detail-description"]}}
{"op":"add","path":"/elements/detail-seller","value":{"type":"Detail","props":{"label":"Seller","value":{"$item":"vendor"}},"children":[]}}
{"op":"add","path":"/elements/detail-seller-address","value":{"type":"Detail","props":{"label":"Seller address","value":{"$item":"vendor_address"}},"children":[]}}
{"op":"add","path":"/elements/detail-siret","value":{"type":"Detail","props":{"label":"SIRET","value":{"$item":"vendor_siret"}},"children":[]}}
{"op":"add","path":"/elements/detail-vat-number","value":{"type":"Detail","props":{"label":"VAT number","value":{"$item":"vendor_vat_number"}},"children":[]}}
{"op":"add","path":"/elements/detail-billed-to","value":{"type":"Detail","props":{"label":"Billed to","value":{"$item":"company_name"}},"children":[]}}
{"op":"add","path":"/elements/detail-billing-address","value":{"type":"Detail","props":{"label":"Billing address","value":{"$item":"company_address"}},"children":[]}}
{"op":"add","path":"/elements/detail-invoice-number","value":{"type":"Detail","props":{"label":"Invoice no.","value":{"$item":"invoice_number"}},"children":[]}}
{"op":"add","path":"/elements/detail-reference","value":{"type":"Detail","props":{"label":"Reference","value":{"$item":"invoice_id"}},"children":[]}}
{"op":"add","path":"/elements/detail-time","value":{"type":"Detail","props":{"label":"Time","value":{"$item":"time"}},"children":[]}}
{"op":"add","path":"/elements/detail-description","value":{"type":"Detail","props":{"label":"What was bought","value":{"$item":"description"}},"children":[]}}
{"op":"add","path":"/elements/classification-rail","value":{"type":"Stack","props":{"direction":"vertical","gap":"md","align":"start"},"children":["category-badge","category-explanation","vat-rates"]}}
{"op":"add","path":"/elements/category-badge","value":{"type":"Badge","props":{"text":{"$item":"category/category"},"variant":"secondary"},"children":[]}}
{"op":"add","path":"/elements/category-explanation","value":{"type":"Text","props":{"text":{"$item":"category/explanation"},"variant":"muted"},"children":[]}}
{"op":"add","path":"/elements/vat-rates","value":{"type":"MthdsResult","props":{"path":"vat_rates"},"children":[]}}
{"op":"add","path":"/elements/raw-text-fold","value":{"type":"Collapsible","props":{"title":"Raw text from the document","defaultOpen":false},"children":["raw-text"]}}
{"op":"add","path":"/elements/raw-text","value":{"type":"Text","props":{"text":{"$item":"text"},"variant":"code"},"children":[]}}
